// ===== SOLVENCY II STANDARD FORMULA ENGINE v2.2 — n8n Code node (Run Once for All Items) =====
// Corrections v2.1 : ordre matrice BSCR, matrice Non-Vie, taux d'impôt en %, regex SCR (exclusion "de base"), priorité R0220
const raw = $input.first().json;
const payload = raw.body ?? raw;
const OPT = { tolerancePct: 0.5, amcrDefault: 4.0, taxRate: 0.25, lacTpRate: 0, watchlist: 130, exportXlsx: false, ...(payload.options || {}) };

const warnings = [];
const warn = (m) => { if (!warnings.includes(m)) warnings.push(m); };
const r2 = (x) => (Number.isFinite(x) ? Math.round(x * 100) / 100 : 0);
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
const slug = (s) => norm(s).replace(/[^a-z0-9]/g, '');

// Parse robuste : "1 234,56", "1.234,56", "(12,3)", "12,5%"
const num = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  if (v === null || v === undefined) return null;
  let s = String(v).trim().replace(/[\s\u00a0€%]/g, '');
  if (!s) return null;
  const neg = /^\(.*\)$/.test(s);
  s = s.replace(/[()]/g, '');
  if (s.includes(',') && s.includes('.')) s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else s = s.replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? (neg ? -n : n) : null;
};
// Tout est ramené en M€
const scale = (u) => {
  const x = norm(u);
  if (/^(md|mrd|bn|milliard|billion)/.test(x)) return 1e3;
  if (/^(k|milliers|thousand)/.test(x)) return 1e-3;
  if (/^(eur|euro|€)/.test(x)) return 1e-6;
  return 1; // M€, millions, ratio, %
};
const parseCode = (c) => {
  const s = String(c || '').toUpperCase().replace(/\s/g, '');
  const t = s.match(/S\.?(\d{2})\.?(\d{2})/), r = s.match(/R(\d{4})/), k = s.match(/C(\d{4})/);
  return { tpl: t ? `S.${t[1]}.${t[2]}` : null, row: r ? 'R' + r[1] : null, col: k ? 'C' + k[1] : null };
};

// ---------- 1. INGESTION (accepte data[] ou sheets{}, colonnes code/libelle/valeur OU Brut/Net) ----------
const IGNORE_SHEET = /pieuvre|synthese|matric|controle|result/i;
let src = [];
if (payload.sheets && !Array.isArray(payload.sheets)) {
  for (const [name, rows] of Object.entries(payload.sheets)) if (!IGNORE_SHEET.test(name) && Array.isArray(rows)) src.push(...rows);
} else if (Array.isArray(payload.data)) src = payload.data;
if (!src.length) throw new Error('Aucune ligne QRT reçue (payload.data ou payload.sheets).');

const entries = [];
for (const r of src) {
  if (!r || typeof r !== 'object') continue;
  const o = {};
  for (const [k, v] of Object.entries(r)) o[slug(k)] = v;
  const ks = Object.keys(o);
  const f = (re) => ks.find((k) => re.test(k));
  const kCode = f(/^(code|codeeiopa|codenoeud|ref|refeiopa)$/), kLab = f(/^(libelle|label|rubrique|name|nom)/);
  const kNet = f(/^(montant)?net/), kBrut = f(/^(montant)?brut/), kVal = f(/^(valeur|value|montant)$/), kUnit = f(/^unit/);
  const sc = scale(kUnit ? o[kUnit] : '');
  const m = (k) => { const n = k ? num(o[k]) : null; return n === null ? null : n * sc; };
  const code = String(kCode ? o[kCode] ?? '' : '');
  const e = { code, label: norm(kLab ? o[kLab] : ''), ...parseCode(code), net: m(kNet), brut: m(kBrut), val: m(kVal) };
  if (e.net === null && e.brut === null && e.val === null) continue;
  entries.push(e);
}
const amt = (e, b) => (e ? (b === 'brut' ? e.brut ?? e.val ?? e.net : e.net ?? e.val ?? e.brut) ?? null : null);

// ---------- 2. DICTIONNAIRE : [gabarit, [[ligne, colonne?]...], regex libellé, regex exclusion] ----------
const SPEC = {
  irUp: ['S.26.01', [['R0110']], /taux.*(hauss|up|increase)|interest.*(up|increase)/],
  irDn: ['S.26.01', [['R0120']], /taux.*(baiss|down|decrease)|interest.*(down|decrease)/],
  eq: ['S.26.01', [['R0200']], /action|equity/],
  prop: ['S.26.01', [['R0300']], /immobilier|property/],
  sp: ['S.26.01', [['R0400']], /spread/],
  fx: ['S.26.01', [['R0500']], /change|currency|\bfx\b/],
  conc: ['S.26.01', [['R0600']], /concentration/],
  def1: ['S.26.02', [['R0100']], /type 1/],
  def2: ['S.26.02', [['R0200']], /type 2/],
  l_mort: ['S.26.03', [['R0100']], /mortalit/],
  l_long: ['S.26.03', [['R0200']], /longevit/],
  l_dis: ['S.26.03', [['R0300']], /invalidit|morbidit|disability/],
  l_lapse: ['S.26.03', [['R0400']], /rachat|lapse/],
  l_exp: ['S.26.03', [['R0500']], /frais|expense/],
  l_rev: ['S.26.03', [['R0600']], /revision|rentes/],
  l_cat: ['S.26.03', [['R0700']], /catastrophe|\bcat\b/],
  h_slt: ['S.26.04', [['R0100']], /\bslt\b|similaire a la vie/, /non similaire|nslt/],
  h_nslt: ['S.26.04', [['R0200']], /nslt|non similaire/],
  h_cat: ['S.26.04', [['R0300']], /catastrophe|\bcat\b/],
  n_pr: ['S.26.05', [['R0100']], /prime|premium/],
  n_cat: ['S.26.05', [['R0200'], ['R0300']], /catastrophe|\bcat\b/],
  n_lapse: ['S.26.05', [['R0300'], ['R0200']], /resiliation|lapse/],
  repMkt: ['S.25.01', [['R0010']], /^(risque de marche|market risk)$/],
  repDef: ['S.25.01', [['R0020']], /defaut de contrepartie|counterparty/],
  repLife: ['S.25.01', [['R0030']], /souscription vie|life underwriting/],
  repHlth: ['S.25.01', [['R0040']], /souscription sante|health underwriting/],
  repNl: ['S.25.01', [['R0050']], /souscription non-vie|non-life underwriting/],
  intang: ['S.25.01', [['R0070']], /incorporel|intangible/],
  repBscr: ['S.25.01', [['R0100']], /bscr|scr de base|basic scr/],
  op: ['S.25.01', [['R0130']], /operationnel|operational/],
  lacTp: ['S.25.01', [['R0140']], /absorption.*provisions techniques|technical provisions.*(absorb|loss)|lac tp/],
  lacDt: ['S.25.01', [['R0150']], /absorption.*impots differes|deferred tax.*(absorb|loss)|lac dt/],
  // CORRECTIF : R0220 (SCR final, add-on inclus) prioritaire sur R0200 ; exclusion de "SCR de base"
  repScr: ['S.25.01', [['R0220'], ['R0200']], /^(scr|solvency capital requirement)/, /bscr|de base|basic|mcr|ratio/],
  prem_vie: ['S.25.01', [['R0131']], /primes.*vie/, /non[- ]vie/],
  prem_nv: ['S.25.01', [['R0132']], /primes.*non[- ]vie/],
  be_vie: ['S.25.01', [['R0133']], /best estimate vie/],
  be_nv: ['S.25.01', [['R0134']], /best estimate non[- ]vie/],
  frais_uc: ['S.25.01', [['R0135']], /unites de compte|\buc\b/],
  fdb: ['S.25.01', [['R0460']], /participation aux benefices|\bfdb\b/],
  tax: ['S.25.01', [['R0151']], /taux d.?impot|tax rate/],
  dtl: ['S.25.01', [['R0152']], /impots differes passifs|\bdtl\b/],
  mcrLin: ['S.28.01', [['R0010']], /lineaire|linear/],
  amcr: ['S.28.01', [['R0330']], /amcr|plancher|absolute/],
  mcrRep: ['S.28.01', [['R0400'], ['R0310']], /mcr/, /lineaire|linear|amcr|plancher|ratio|eligible|fonds propres/],
  t1u: ['S.23.01', [['R0500', 'C0020'], ['R0020']], /non[- ]restreint|unrestricted/],
  t1r: ['S.23.01', [['R0500', 'C0030'], ['R0030']], /restreint|restricted/, /non[- ]restreint|unrestricted/],
  t2: ['S.23.01', [['R0500', 'C0040'], ['R0040']], /tier ?2/],
  t3: ['S.23.01', [['R0500', 'C0050'], ['R0050']], /tier ?3/],
  eofRep: ['S.23.01', [['R0540'], ['R0100']], /eligible/],
};
// Un code n'est accepté que si son libellé (quand il existe) est cohérent ; sinon recherche par libellé.
const resolve = (key) => {
  const [t, rows, lab, exc] = SPEC[key];
  const ok = (e) => (!lab || !e.label || lab.test(e.label)) && !(exc && e.label && exc.test(e.label));
  const byCode = rows.flatMap(([r, c]) => entries.filter((e) => e.tpl === t && e.row === r && (!c || e.col === c)));
  const good = byCode.find(ok);
  if (good) return good;
  const scan = (arr) => arr.find((e) => lab && e.label && lab.test(e.label) && !(exc && exc.test(e.label)));
  const hit = scan(entries.filter((e) => e.tpl === t)) ?? scan(entries.filter((e) => !e.tpl));
  if (hit) return hit;
  if (byCode[0]) warn(`${key}: code ${byCode[0].code} ignoré, libellé incohérent « ${byCode[0].label} »`);
  return null;
};
const R = Object.fromEntries(Object.keys(SPEC).map((k) => [k, resolve(k)]));

// ---------- 3. MATRICES DE CORRÉLATION (Règlement délégué 2015/35) ----------
const sym = (n, pairs) => {
  const M = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
  pairs.forEach(([i, j, v]) => { M[i][j] = v; M[j][i] = v; });
  return M;
};
const agg = (v, M) => Math.sqrt(Math.max(0, v.reduce((a, vi, i) => a + v.reduce((b, vj, j) => b + M[i][j] * vi * vj, 0), 0)));
const MKT_M = (A) => sym(6, [[0, 1, A], [0, 2, A], [0, 3, A], [0, 4, 0.25], [1, 2, 0.75], [1, 3, 0.75], [1, 4, 0.25], [2, 3, 0.5], [2, 4, 0.25], [3, 4, 0.25]]); // taux, actions, immo, spread, change, concentration
const LIFE_M = sym(7, [[0, 1, -0.25], [0, 2, 0.25], [0, 4, 0.25], [0, 6, 0.25], [1, 3, 0.25], [1, 4, 0.25], [1, 5, 0.25], [2, 4, 0.5], [2, 6, 0.25], [3, 4, 0.5], [3, 6, 0.25], [4, 5, 0.5], [4, 6, 0.25]]);
const HLTH_M = sym(3, [[0, 1, 0.5], [0, 2, 0.25], [1, 2, 0.25]]);
// Non-vie : prime et réserve (0), résiliation (1), catastrophe (2) — 0,25 pour chaque paire (cf. Art. 114 RD 2015/35 ; lapse à confirmer sur le texte consolidé)
const NL_M = sym(3, [[0, 1, 0.25], [0, 2, 0.25], [1, 2, 0.25]]);
// CORRECTIF : ordre des modules de MODS = marché (0), non-vie (1), vie (2), santé (3), défaut (4)
// Annexe IV : marché/autres 0,25 ; défaut/non-vie 0,5 ; vie/non-vie 0 ; santé/non-vie 0 ; autres paires 0,25
const BSCR_M = sym(5, [
  [0, 1, 0.25], [0, 2, 0.25], [0, 3, 0.25], [0, 4, 0.25],
  [1, 2, 0], [1, 3, 0], [1, 4, 0.5],
  [2, 3, 0.25], [2, 4, 0.25],
  [3, 4, 0.25],
]);

// ---------- 4. CALCUL D'UNE BASE (net = après atténuation, brut = avant) ----------
const MODS = [
  ['MKT', 'Risque de marché', 'repMkt', '#1E3A8A', 'Marché'],
  ['NL', 'Souscription Non-Vie', 'repNl', '#2563EB', 'Souscription Non-Vie'],
  ['LIFE', 'Souscription Vie', 'repLife', '#3B82F6', 'Vie'],
  ['HLTH', 'Souscription Santé', 'repHlth', '#60A5FA', 'Santé'],
  ['DEF', 'Défaut de contrepartie', 'repDef', '#64748B', 'Contrepartie'],
];
const compute = (b) => {
  const w = b === 'net' ? warn : () => {};
  const A = (k) => amt(R[k], b);
  const pos = (x) => Math.max(x ?? 0, 0);
  const any = (a) => a.some((x) => x !== null);
  const simple = (keys, M, ids, labels) => { const v = keys.map(A); if (!any(v)) return null; const vec = v.map(pos); return { total: agg(vec, M), vec, ids, labels }; };
  const calc = {
    MKT: () => {
      const v = ['irUp', 'irDn', 'eq', 'prop', 'sp', 'fx', 'conc'].map(A);
      if (!any(v)) return null;
      const [u, d, eq, pr, sp, fx, cn] = v.map(pos);
      const up = u >= d; // Art. 164 : A = 0 si choc à la hausse dominant, 0,5 si à la baisse
      const vec = [up ? u : d, eq, pr, sp, fx, cn];
      return { total: agg(vec, MKT_M(up ? 0 : 0.5)), vec, regime: up ? 'IR_UP (A=0.0)' : 'IR_DOWN (A=0.5)',
        ids: ['IR', 'EQ', 'PROP', 'SP', 'FX', 'CONC'], labels: [`Taux d'intérêt (choc ${up ? 'haussier' : 'baissier'} retenu)`, 'Actions', 'Immobilier', 'Spread', 'Change', 'Concentration'] };
    },
    NL: () => simple(['n_pr', 'n_lapse', 'n_cat'], NL_M, ['PR', 'LAPSE', 'CAT'], ['Prime et réserve', 'Résiliation', 'Catastrophe']),
    LIFE: () => simple(['l_mort', 'l_long', 'l_dis', 'l_lapse', 'l_exp', 'l_rev', 'l_cat'], LIFE_M, ['MORT', 'LONG', 'INV', 'LAPSE', 'EXP', 'REV', 'CAT'], ['Mortalité', 'Longévité', 'Invalidité / morbidité', 'Rachat', 'Frais', 'Révision des rentes', 'Catastrophe vie']),
    HLTH: () => simple(['h_slt', 'h_nslt', 'h_cat'], HLTH_M, ['SLT', 'NSLT', 'CAT'], ['Santé similaire à la vie (SLT)', 'Santé non similaire à la vie (NSLT)', 'Catastrophe santé']),
    DEF: () => { // NB : seuil de 15 % de l'Art. 189 non implémenté
      const v = ['def1', 'def2'].map(A); if (!any(v)) return null;
      const [t1, t2] = v.map(pos);
      return { total: Math.sqrt(t1 * t1 + 1.5 * t1 * t2 + t2 * t2), vec: [t1, t2], ids: ['T1', 'T2'], labels: ['Type 1 (réassureurs, banques)', 'Type 2 (intermédiaires, assurés)'] };
    },
  };
  const mods = {};
  for (const [id, lib, rep] of MODS) {
    const c = calc[id](), rp = A(rep);
    mods[id] = c ? { ...c, source: 'sous-modules', reported: rp } : { total: pos(rp), vec: [], ids: [], labels: [], source: rp === null ? 'absent' : 'reporté', reported: rp };
    if (!c && rp === null) w(`${lib} : aucune donnée (ni sous-modules ni S.25.01) → 0`);
  }
  const ids = MODS.map((m) => m[0]);
  const vec = ids.map((i) => mods[i].total);
  const core = agg(vec, BSCR_M);
  const intang = pos(A('intang'));
  const bscr = core + intang; // actifs incorporels ajoutés linéairement
  const divers = core - vec.reduce((a, c) => a + c, 0);

  let op = A('op'), opSrc = 'reporté';
  if (op === null) {
    const [pv, pn, bv, bn, fu] = ['prem_vie', 'prem_nv', 'be_vie', 'be_nv', 'frais_uc'].map(A);
    if (any([pv, pn, bv, bn])) {
      op = Math.min(0.3 * bscr, Math.max(0.04 * pos(pv) + 0.03 * pos(pn), 0.0045 * pos(bv) + 0.03 * pos(bn))) + 0.25 * pos(fu);
      opSrc = 'calculé (simplifié)';
      w('Risque opérationnel recalculé en version simplifiée (sans plafond de croissance ni détail UC)');
    } else { op = 0; opSrc = 'absent'; w('Risque opérationnel absent (S.25.01 R0130) → 0'); }
  }
  op = pos(op);

  let lacTp = A('lacTp'), lacTpSrc = 'reporté';
  const fdb = A('fdb');
  if (lacTp === null) {
    if (fdb !== null && OPT.lacTpRate > 0) { lacTp = Math.min(fdb, OPT.lacTpRate * bscr); lacTpSrc = 'calculé (options.lacTpRate)'; }
    else { lacTp = 0; lacTpSrc = 'absent'; if (fdb) w(`LAC TP absente alors que la PB future vaut ${r2(fdb)} M€ : fournir S.25.01 R0140 ou options.lacTpRate`); }
  }
  lacTp = -Math.abs(lacTp);
  if (fdb !== null && -lacTp > fdb + 1e-9) w(`LAC TP (${r2(-lacTp)}) supérieure à la PB future (${r2(fdb)}) : à justifier`);

  // CORRECTIF : taux d'impôt fourni en pourcentage (ex. 25 ou « 25 % ») → fraction
  let tax = A('tax') ?? OPT.taxRate;
  if (tax > 1) tax /= 100;
  const dtl = A('dtl');
  const dtCap = Math.min(dtl ?? Infinity, tax * Math.max(0, bscr + op + lacTp));
  let lacDt = A('lacDt'), lacDtSrc = 'reporté';
  if (lacDt === null) {
    if (dtl !== null) { lacDt = dtCap; lacDtSrc = 'calculé = min(DTL, taux IS × (BSCR+Op+LAC TP))'; } else { lacDt = 0; lacDtSrc = 'absent'; }
  } else if (Number.isFinite(dtCap) && Math.abs(lacDt) > dtCap + 1e-6) w(`LAC DT (${r2(Math.abs(lacDt))}) supérieure à la capacité DTL/taux IS (${r2(dtCap)}) : recouvrabilité à justifier`);
  lacDt = -Math.abs(lacDt);
  const adjCap = bscr + op; // l'ajustement total ne peut pas dépasser BSCR + Op
  if (-lacTp > adjCap) { lacTp = -adjCap; w('LAC TP plafonnée à BSCR + Op'); }
  if (-lacTp - lacDt > adjCap + 1e-9) { lacDt = -Math.max(0, adjCap + lacTp); w('LAC DT plafonnée : ajustement total > BSCR + Op'); }

  const scr = Math.max(0, bscr + op + lacTp + lacDt);
  return { mods, core, divers, intang, bscr, op, opSrc, lacTp, lacTpSrc, lacDt, lacDtSrc, scr };
};
const N = compute('net'), B = compute('brut');
const scr = r2(N.scr);

// ---------- 5. RÉCONCILIATION AVEC LES MONTANTS REPORTÉS ----------
const recon = [];
const cmp = (name, calc, rep) => {
  if (rep === null || rep === undefined) return;
  const d = calc - rep, pct = rep ? (d / Math.abs(rep)) * 100 : calc ? 100 : 0;
  const ok = Math.abs(d) <= 0.05 || Math.abs(pct) <= OPT.tolerancePct;
  recon.push({ Indicateur: name, 'Calculé (M€)': r2(calc), 'Reporté (M€)': r2(rep), 'Écart (M€)': r2(d), 'Écart (%)': r2(pct), Statut: ok ? 'OK' : 'ÉCART' });
  if (!ok) warn(`Écart ${name} : calculé ${r2(calc)} vs reporté ${r2(rep)} M€ (${r2(pct)} %)`);
};
for (const [id, lib] of MODS) if (N.mods[id].source === 'sous-modules') cmp(lib, N.mods[id].total, N.mods[id].reported);
cmp('BSCR', N.bscr, amt(R.repBscr, 'net'));
if (N.opSrc !== 'reporté') cmp('Risque opérationnel', N.op, amt(R.op, 'net'));
cmp('SCR', N.scr, amt(R.repScr, 'net'));

// ---------- 6. MCR ----------
let amcr = amt(R.amcr, 'net');
if (amcr === null) { amcr = OPT.amcrDefault; warn(`AMCR absent : valeur par défaut ${amcr} M€ (à paramétrer selon le type d'organisme)`); }
const mcrLin = amt(R.mcrLin, 'net');
let mcr;
if (mcrLin !== null) mcr = Math.max(Math.min(Math.max(mcrLin, 0.25 * N.scr), 0.45 * N.scr), amcr);
else mcr = amt(R.mcrRep, 'net') ?? Math.max(0.25 * N.scr, amcr);
mcr = r2(mcr);

// ---------- 7. FONDS PROPRES : classement et éligibilité (Art. 82) ----------
const [t1u, t1r, t2r, t3r] = ['t1u', 't1r', 't2', 't3'].map((k) => amt(R[k], 'net'));
let available, eligScr, eligMcr, tier1Ok = null, t1Elig = null, t2Elig = null, t3Elig = null;
if ([t1u, t1r, t2r, t3r].some((x) => x !== null)) {
  const u = t1u ?? 0, rr = t1r ?? 0, t2 = t2r ?? 0, t3 = t3r ?? 0;
  available = u + rr + t2 + t3;
  const rElig = Math.min(rr, 0.25 * u); // Tier 1 restreint <= 20 % du Tier 1 total
  t1Elig = u + rElig;
  const t2Avail = t2 + (rr - rElig); // excédent reclassé en Tier 2
  t3Elig = Math.min(t3, 0.15 * N.scr);
  t2Elig = Math.min(t2Avail, Math.max(0, 0.5 * N.scr - t3Elig)); // Tier 2 + Tier 3 <= 50 % du SCR
  eligScr = t1Elig + t2Elig + t3Elig;
  eligMcr = t1Elig + Math.min(t2Avail, 0.2 * mcr); // MCR : Tier 3 exclu, Tier 2 <= 20 %
  tier1Ok = t1Elig >= 0.5 * N.scr;
  if (!tier1Ok) warn('Tier 1 éligible inférieur à 50 % du SCR');
  if (t1Elig < 0.8 * mcr) warn('Tier 1 éligible inférieur à 80 % du MCR');
} else {
  eligScr = amt(R.eofRep, 'net') ?? 0; available = eligScr; eligMcr = eligScr;
  warn('Détail Tier 1/2/3 absent : fonds propres éligibles repris tels que reportés');
}
const ratio = N.scr > 0 ? r2((eligScr / N.scr) * 100) : 0;
const mcrRatio = mcr > 0 ? r2((eligMcr / mcr) * 100) : 0;
const status = mcrRatio < 100 ? 'BREACH_MCR' : ratio < 100 ? 'BREACH_SCR' : ratio < OPT.watchlist ? 'WATCHLIST' : 'COMPLIANT';

// ---------- 8. ARBRE « PIEUVRE » ----------
const tree = []; let ord = 0;
const add = (niv, code, parent, lib, b, n, color, ref = '') => tree.push({
  Niveau: niv, Code_Noeud: code, Code_Parent: parent, 'Libellé': lib, 'Brut (M€)': r2(b), 'Net (M€)': r2(n), 'Effet mitigation (M€)': r2(n - b),
  'Poids dans SCR (%)': N.scr ? r2((Math.abs(n) / N.scr) * 100) : 0, Ordre_Tentacule: ++ord, Couleur_Hex: color, Ref_EIOPA: ref });
add(0, 'SCR', '', 'SCR total', B.scr, N.scr, '#000000', 'S.25.01.R0200');
